#!/usr/bin/env python3
"""
ScalaBass — descriptions de gammes relues et corrigées
======================================================
Ces textes remplacent, pour la basse comme pour la guitare, les descriptions
dont la théorie était fausse ou imprécise (intervalles cités qui n'existent
pas dans la gamme, accords d'usage inversés, quarts de ton passés sous
silence). Ils sont volontairement neutres quant à l'instrument.

Chaque affirmation chiffrée (degrés, secondes augmentées, demi-tons) est
contrôlée par _generator/audit_theory.py contre les intervalles de SCALE_DEFS.
"""

FIX_FR = {
    "blues_hex": "La gamme blues hexatonique est une pentatonique mineure à laquelle on ajoute la seconde majeure (1 2 ♭3 4 5 ♭7). Cette sixième note comble le saut entre la tonique et la tierce mineure et donne des phrases plus chantantes, proches du dorien sans sa sixte. Très utilisée dans le blues-rock et le rock alternatif.",
    "penta_maj7": "La pentatonique majeure 7 est une pentatonique majeure dont la sixte est remplacée par la septième majeure (1 2 3 5 7). Elle dessine directement l'accord majeur 7 et sa neuvième : idéale sur les accords maj7 et maj9, pour des lignes élégantes sans la quarte, qui frotterait avec la tierce.",
    "dim": "La gamme diminuée ton-demi-ton alterne tons et demi-tons : 8 notes, parfaitement symétrique. Elle se répète à l'identique toutes les tierces mineures, donc une même forme sert pour quatre toniques. C'est la gamme de l'accord diminué 7 : elle contient ses quatre notes, chacune précédée d'un demi-ton.",
    "dim_ht": "La gamme diminuée demi-ton-ton commence par un demi-ton. Elle contient la tierce majeure et la septième mineure, donc un accord de dominante, entouré de ♭9, ♯9, ♯11 et 13. C'est la gamme des accords 7♭9 et 13♭9 qui résolvent vers un accord majeur. Symétrique, elle se décale telle quelle toutes les tierces mineures.",
    "hung_min": "La mineure hongroise est une mineure harmonique dont la quarte est augmentée (1 2 ♭3 ♯4 5 ♭6 7). Elle compte donc deux secondes augmentées : entre ♭3 et ♯4, puis entre ♭6 et 7. C'est la couleur tsigane d'Europe centrale par excellence, reprise par Liszt et Brahms puis par le metal néoclassique.",
    "hung_maj": "La majeure hongroise (1 ♯2 3 ♯4 5 6 ♭7) associe une seconde augmentée, une quarte augmentée et une septième mineure. Elle sonne sur un accord de dominante : sa ♯9 et sa ♯11 en font une cousine du lydien dominant et de la gamme diminuée demi-ton-ton, avec une couleur d'Europe centrale.",
    "gypsy_maj": "La gamme gitane espagnole a exactement les notes du phrygien dominant, cinquième mode de la mineure harmonique : seconde mineure, tierce majeure, sixte et septième mineures. La seconde augmentée entre ♭2 et 3 est la signature du flamenco. À ne pas confondre avec la double harmonique, parfois elle aussi appelée « tzigane majeure », dont la septième est majeure.",
    "persian": "La gamme persane (1 ♭2 3 4 ♭5 ♭6 7) est une double harmonique dont la quinte est diminuée. Elle garde les deux secondes augmentées (♭2–3 et ♭6–7) et y ajoute trois notes serrées en demi-tons autour de la quarte. Son nom est occidental : c'est une construction théorique plus qu'un mode réellement joué en Iran.",
    "arabic": "Aussi appelée majeure locrienne, cette gamme a une moitié basse majeure (1 2 3 4) et une moitié haute locrienne (♭5 ♭6 ♭7). Cinq de ses intervalles sont des tons entiers, d'où une parenté d'oreille avec la gamme par tons. Malgré son nom, elle ne correspond à aucun maqam précis : c'est une appellation occidentale.",
    "enigmatic": "La gamme énigmatique (1 ♭2 3 ♯4 ♯5 ♯6 7) a été proposée comme défi d'harmonisation et mise en musique par Verdi dans son Ave Maria de 1889. Après la seconde mineure et la tierce majeure, elle monte par tons entiers puis se termine par deux demi-tons : aucune tonalité classique ne s'en dégage, ce qui fait tout son intérêt.",
    "napolitaine_maj": "La napolitaine majeure est une mineure mélodique dont la seconde est abaissée (1 ♭2 ♭3 4 5 6 7). Sa tierce est donc mineure : « majeure » désigne ici la sixte et la septième majeures, par opposition à la napolitaine mineure. Entre ♭3 et 7 elle progresse uniquement par tons, ce qui lui donne une couleur flottante.",
    "napolitaine_min": "La napolitaine mineure est une mineure harmonique dont la seconde est abaissée (1 ♭2 ♭3 4 5 ♭6 7). Elle réunit la seconde mineure du phrygien et la sensible de la mineure harmonique, avec une seconde augmentée entre ♭6 et 7. Son ♭2 renvoie à l'accord de sixte napolitaine de l'opéra du XVIIIᵉ siècle.",
    "nikriz": "Le maqam Nikriz (1 2 ♭3 ♯4 5 6 ♭7) se reconnaît à la seconde augmentée entre sa tierce mineure et sa quarte augmentée. En tempérament égal, ce sont les notes du dorien ♯4, appelé aussi mineure roumaine ou dorien ukrainien. Très présent dans les musiques arabe, turque, klezmer et balkanique.",
    "insen": "La gamme Insen est une pentatonique japonaise sans tierce (1 ♭2 4 5 ♭7), associée au répertoire du koto. Sa seconde mineure lui donne une couleur proche du phrygien, mais l'absence de tierce la laisse suspendue, ni majeure ni mineure.",
    "iwato": "La gamme Iwato (1 ♭2 4 ♭5 ♭7) est la plus tendue des pentatoniques japonaises. Elle contient deux demi-tons, entre 1 et ♭2 puis entre 4 et ♭5, et n'a ni tierce ni quinte juste : ce sont les notes du mode locrien réduites à cinq.",
    "man_gong": "Cette pentatonique (1 ♭3 4 ♭6 ♭7) est le troisième mode de la pentatonique majeure. On peut la voir comme une pentatonique mineure dont la quinte est remplacée par la sixte mineure : sans quinte juste, elle sonne plus sombre et moins stable. Elle sert sur les accords mineurs quand on veut éviter l'appui sur la quinte.",
    "algerian": "La gamme algérienne à huit notes est une mineure harmonique à laquelle on ajoute la quarte augmentée (1 2 ♭3 4 ♯4 5 ♭6 7). Ses deux quartes voisines, juste et augmentée, permettent de passer d'une couleur mineure harmonique à une couleur mineure hongroise au sein d'une même phrase.",
    "rast": "Le maqam Rast est le mode fondamental de la musique arabe. Sa tierce et sa septième sont des degrés neutres, situés un quart de ton sous les degrés majeurs : aucun instrument à frettes ne peut les jouer tels quels. La version donnée ici est l'approximation tempérée la plus courante, identique au mixolydien.",
    "bayati": "Le maqam Bayati est l'un des plus joués de la musique arabe. Son deuxième degré est neutre, à mi-chemin entre la seconde mineure et la seconde majeure : c'est ce quart de ton qui fait sa couleur. Sur un manche fretté on l'approche par le mode phrygien, donné ici, en gardant à l'esprit que la vraie note se trouve entre deux cases.",
    "dorian_b2": "Le dorien ♭2 (mode II de la mineure mélodique, ou phrygien ♮6) combine la seconde mineure du phrygien et la sixte majeure du dorien. En jazz, c'est la gamme des accords 7sus4(♭9) ; elle sert aussi sur un accord mineur 7 pour une couleur plus sombre que le dorien.",
    "bhairav": "Le raga Bhairav est l'un des ragas majeurs de la musique hindoustanie, joué traditionnellement au lever du soleil. Sa seconde et sa sixte mineures encadrent une tierce et une septième majeures : en tempérament égal, ce sont les notes de la double harmonique.",
    "yo": "La gamme Yo (1 2 4 5 6) est une pentatonique japonaise sans tierce, utilisée dans la musique populaire et festive. Sans demi-ton, elle est plus claire que les gammes In ; c'est un mode de la pentatonique majeure, qu'on peut jouer aussi bien sur un accord majeur que mineur.",
    "hijaz_kar": "Le maqam Hijaz Kar enchaîne deux tétracordes Hijaz : une seconde augmentée entre ♭2 et 3, une autre entre ♭6 et 7. En tempérament égal, ce sont les notes de la double harmonique (1 ♭2 3 4 5 ♭6 7). Très utilisé dans les musiques arabe et turque classiques.",
    "half_dim": "La gamme demi-diminuée est le sixième mode de la mineure mélodique : un locrien dont la seconde est majeure (1 2 ♭3 4 ♭5 ♭6 ♭7). C'est la gamme de référence sur les accords m7♭5 du ii-V-i mineur, préférée au locrien dont la seconde mineure frotte avec la fondamentale.",
    "ionian_s5": "L'ionien ♯5 (mode III de la mineure harmonique) est une gamme majeure dont la quinte est augmentée. Il se joue sur les accords majeur 7 ♯5, où il garde la quarte juste que le lydien augmenté remplace par une quarte augmentée.",
}

FIX_EN = {
    "blues_hex": "The hexatonic blues scale is a minor pentatonic with an added major second (1 2 ♭3 4 5 ♭7). That sixth note fills the leap between the root and the minor third and makes for more singable lines, close to Dorian without its sixth. Widely used in blues-rock and alternative rock.",
    "penta_maj7": "The major 7 pentatonic is a major pentatonic whose sixth is replaced by the major seventh (1 2 3 5 7). It outlines the major 7 chord and its ninth: ideal over maj7 and maj9 chords, for elegant lines without the fourth, which would clash with the third.",
    "dim": "The whole-half diminished scale alternates whole steps and half steps: 8 notes, perfectly symmetrical. It repeats every minor third, so one shape serves four roots. It is the scale of the diminished 7 chord: it contains its four notes, each approached from a half step below.",
    "dim_ht": "The half-whole diminished scale starts with a half step. It contains the major third and the minor seventh, so a dominant chord, surrounded by ♭9, ♯9, ♯11 and 13. It is the scale for 7♭9 and 13♭9 chords resolving to a major chord. Being symmetrical, it moves unchanged every minor third.",
    "hung_min": "Hungarian minor is a harmonic minor with a raised fourth (1 2 ♭3 ♯4 5 ♭6 7). It therefore has two augmented seconds: between ♭3 and ♯4, then between ♭6 and 7. This is the Central European Gypsy colour, borrowed by Liszt and Brahms and later by neoclassical metal.",
    "hung_maj": "Hungarian major (1 ♯2 3 ♯4 5 6 ♭7) combines an augmented second, an augmented fourth and a minor seventh. It works over a dominant chord: its ♯9 and ♯11 make it a cousin of Lydian dominant and of the half-whole diminished scale, with a Central European flavour.",
    "gypsy_maj": "The Spanish Gypsy scale has exactly the notes of Phrygian dominant, the fifth mode of harmonic minor: minor second, major third, minor sixth and minor seventh. The augmented second between ♭2 and 3 is the signature of flamenco. Not to be confused with the double harmonic scale, sometimes also called Gypsy major, whose seventh is major.",
    "persian": "The Persian scale (1 ♭2 3 4 ♭5 ♭6 7) is a double harmonic scale with a flattened fifth. It keeps both augmented seconds (♭2–3 and ♭6–7) and adds three notes packed in half steps around the fourth. The name is Western: it is a theoretical construct more than a mode actually played in Iran.",
    "arabic": "Also called major Locrian, this scale has a major lower half (1 2 3 4) and a Locrian upper half (♭5 ♭6 ♭7). Five of its steps are whole tones, hence its kinship with the whole-tone scale. Despite the name it does not match any specific maqam: it is a Western label.",
    "enigmatic": "The enigmatic scale (1 ♭2 3 ♯4 ♯5 ♯6 7) was put forward as a harmonisation puzzle and set to music by Verdi in his 1889 Ave Maria. After the minor second and the major third it climbs by whole tones and ends with two half steps: no classical key emerges from it, which is the whole point.",
    "napolitaine_maj": "Neapolitan major is a melodic minor with a lowered second (1 ♭2 ♭3 4 5 6 7). Its third is therefore minor: \"major\" refers to the major sixth and seventh, as opposed to Neapolitan minor. From ♭3 to 7 it moves in whole tones only, which gives it a floating colour.",
    "napolitaine_min": "Neapolitan minor is a harmonic minor with a lowered second (1 ♭2 ♭3 4 5 ♭6 7). It combines the minor second of Phrygian with the leading tone of harmonic minor, with an augmented second between ♭6 and 7. Its ♭2 points to the Neapolitan sixth chord of 18th-century opera.",
    "nikriz": "The Nikriz maqam (1 2 ♭3 ♯4 5 6 ♭7) is recognised by the augmented second between its minor third and its augmented fourth. In equal temperament these are the notes of Dorian ♯4, also called Romanian minor or Ukrainian Dorian. Very common in Arabic, Turkish, klezmer and Balkan music.",
    "insen": "The Insen scale is a Japanese pentatonic with no third (1 ♭2 4 5 ♭7), associated with the koto repertoire. Its minor second gives it a Phrygian-like colour, but the missing third leaves it suspended, neither major nor minor.",
    "iwato": "The Iwato scale (1 ♭2 4 ♭5 ♭7) is the tensest of the Japanese pentatonics. It contains two half steps, between 1 and ♭2 and between 4 and ♭5, and has neither a third nor a perfect fifth: these are the notes of the Locrian mode reduced to five.",
    "man_gong": "This pentatonic (1 ♭3 4 ♭6 ♭7) is the third mode of the major pentatonic. It can be seen as a minor pentatonic whose fifth is replaced by the minor sixth: with no perfect fifth it sounds darker and less stable. Useful over minor chords when you want to avoid leaning on the fifth.",
    "algerian": "The eight-note Algerian scale is a harmonic minor with an added augmented fourth (1 2 ♭3 4 ♯4 5 ♭6 7). Its two neighbouring fourths, perfect and augmented, let you move from a harmonic minor colour to a Hungarian minor colour within a single phrase.",
    "rast": "The Rast maqam is the fundamental mode of Arabic music. Its third and seventh are neutral degrees, a quarter tone below the major ones: no fretted instrument can play them as such. The version given here is the most common equal-tempered approximation, identical to Mixolydian.",
    "bayati": "The Bayati maqam is one of the most played in Arabic music. Its second degree is neutral, halfway between a minor and a major second: that quarter tone is what gives it its colour. On a fretted neck it is approximated by the Phrygian mode, given here, bearing in mind that the real note lies between two frets.",
    "dorian_b2": "Dorian ♭2 (mode II of melodic minor, or Phrygian ♮6) combines the minor second of Phrygian with the major sixth of Dorian. In jazz it is the scale for 7sus4(♭9) chords; it also works over a minor 7 chord for a darker colour than Dorian.",
    "bhairav": "Raga Bhairav is one of the major ragas of Hindustani music, traditionally played at sunrise. Its minor second and minor sixth frame a major third and a major seventh: in equal temperament these are the notes of the double harmonic scale.",
    "yo": "The Yo scale (1 2 4 5 6) is a Japanese pentatonic with no third, used in folk and festive music. With no half step it is brighter than the In scales; it is a mode of the major pentatonic and can be played over a major or a minor chord alike.",
    "hijaz_kar": "The Hijaz Kar maqam chains two Hijaz tetrachords: an augmented second between ♭2 and 3, another between ♭6 and 7. In equal temperament these are the notes of the double harmonic scale (1 ♭2 3 4 5 ♭6 7). Widely used in classical Arabic and Turkish music.",
    "half_dim": "The half-diminished scale is the sixth mode of melodic minor: a Locrian with a major second (1 2 ♭3 4 ♭5 ♭6 ♭7). It is the reference scale over m7♭5 chords in the minor ii-V-i, preferred to Locrian whose minor second clashes with the root.",
    "ionian_s5": "Ionian ♯5 (mode III of harmonic minor) is a major scale with an augmented fifth. It is played over major 7 ♯5 chords, where it keeps the perfect fourth that Lydian augmented replaces with an augmented fourth.",
}


def corrected_desc(scale_id, lang):
    return (FIX_FR if lang == 'fr' else FIX_EN).get(scale_id)
